// Auto-generated — do not edit manually. Run: node build.js
module.exports = {
  "html": "<!DOCTYPE html>\n<html lang=\"zh-TW\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>CVE Web Scanner — NIST NVD</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#f1f5f9;color:#1e293b;line-height:1.55;min-height:100vh}\na{color:#2563eb;text-decoration:none}a:hover{text-decoration:underline}\n\nheader{background:linear-gradient(135deg,#1e3a5f 0%,#1e40af 100%);color:#fff;padding:28px 32px}\nheader h1{font-size:1.55rem;font-weight:800;margin-bottom:4px;letter-spacing:-.02em}\nheader p{font-size:.87rem;opacity:.7;margin-top:4px}\n\nmain{max-width:860px;margin:24px auto;padding:0 16px 40px}\n\n.card{background:#fff;border-radius:12px;padding:22px 26px;margin-bottom:18px;box-shadow:0 1px 4px rgba(0,0,0,.08)}\n.card-title{font-size:.93rem;font-weight:700;color:#1e3a5f;margin-bottom:16px;display:flex;align-items:center;gap:9px}\n.step-badge{background:#1e3a5f;color:#fff;width:22px;height:22px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:.68rem;font-weight:800;flex-shrink:0}\n\n/* Drop zone */\n#drop-zone{border:2px dashed #cbd5e1;border-radius:10px;padding:34px 20px;text-align:center;cursor:pointer;transition:all .18s;background:#f8fafc;user-select:none}\n#drop-zone:hover,#drop-zone.drag-over{border-color:#2563eb;background:#eff6ff}\n#drop-zone.has-file{border-color:#16a34a;background:#f0fdf4;cursor:default}\n.dz-icon{font-size:2rem;display:block;margin-bottom:8px;pointer-events:none}\n.dz-label{font-size:.9rem;color:#475569;font-weight:500;pointer-events:none}\n.dz-sub{font-size:.77rem;color:#94a3b8;margin-top:4px;pointer-events:none}\n#file-input{display:none}\n\n#file-info{display:none;margin-top:11px;font-size:.82rem;color:#475569;background:#f8fafc;border-radius:7px;padding:9px 13px;border-left:3px solid #16a34a}\n#file-info strong{color:#1e293b}\n\n/* Settings */\n.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n@media(max-width:580px){.settings-grid{grid-template-columns:1fr}}\n.form-group{display:flex;flex-direction:column;gap:4px}\n.form-group label{font-size:.74rem;font-weight:700;color:#64748b;text-transform:uppercase;letter-spacing:.05em}\n.form-group input,.form-group select{border:1px solid #e2e8f0;border-radius:7px;padding:8px 10px;font-size:.87rem;color:#1e293b;outline:none;transition:border-color .15s,box-shadow .15s;background:#fff;width:100%}\n.form-group input:focus,.form-group select:focus{border-color:#2563eb;box-shadow:0 0 0 3px rgba(37,99,235,.1)}\n.form-group .hint{font-size:.71rem;color:#94a3b8;margin-top:2px}\n.full-width{grid-column:1/-1}\n\n/* Actions */\n#action-card{display:flex;align-items:center;gap:12px;flex-wrap:wrap}\n#scan-btn{background:#1e3a5f;color:#fff;border:none;border-radius:8px;padding:11px 28px;font-size:.93rem;font-weight:700;cursor:pointer;transition:background .15s;white-space:nowrap}\n#scan-btn:hover:not(:disabled){background:#1e40af}\n#scan-btn:disabled{background:#94a3b8;cursor:not-allowed}\n#cancel-btn{background:transparent;color:#dc2626;border:1.5px solid #dc2626;border-radius:8px;padding:10px 18px;font-size:.87rem;font-weight:600;cursor:pointer;display:none;transition:all .15s}\n#cancel-btn:hover:not(:disabled){background:#fef2f2}\n#cancel-btn:disabled{opacity:.5;cursor:not-allowed}\n#scan-status{font-size:.83rem;color:#64748b}\n\n/* Progress & Result (nested inside tab panels) */\n.inner-section{border-top:1px solid #e2e8f0;margin-top:22px;padding-top:20px}\n.progress-bar-wrap{background:#e2e8f0;border-radius:999px;height:7px;margin-bottom:11px;overflow:hidden}\n.progress-bar{height:100%;background:linear-gradient(90deg,#2563eb,#3b82f6);border-radius:999px;transition:width .4s ease;width:0}\n.progress-stats{font-size:.8rem;color:#64748b;margin-bottom:10px;display:flex;gap:16px;flex-wrap:wrap}\n.progress-stats strong{color:#1e293b}\n.progress-log{background:#0f172a;border-radius:9px;padding:14px 16px;font-family:'Cascadia Code','Fira Mono',Consolas,monospace;font-size:.76rem;color:#94a3b8;max-height:300px;overflow-y:auto;line-height:1.65;word-break:break-all}\n.l-ok{color:#4ade80}.l-warn{color:#fbbf24}.l-err{color:#f87171}.l-info{color:#60a5fa}.l-gray{color:#64748b}.l-b{font-weight:700;color:#e2e8f0}\n.progress-log a{color:#60a5fa;text-decoration:none}.progress-log a:hover{text-decoration:underline}\n.dl-row{display:flex;gap:10px;flex-wrap:wrap}\n.dl-btn{display:inline-flex;align-items:center;gap:8px;border-radius:8px;padding:11px 22px;font-size:.88rem;font-weight:700;text-decoration:none;transition:all .15s;cursor:pointer;border:none}\n.dl-btn.primary{background:#1e3a5f;color:#fff}\n.dl-btn.primary:hover{background:#1e40af;text-decoration:none;color:#fff}\n.dl-btn.secondary{background:#f1f5f9;color:#1e293b;border:1.5px solid #e2e8f0}\n.dl-btn.secondary:hover{background:#e2e8f0;text-decoration:none;color:#1e293b}\n\n/* Portable rows */\n#portable-list{display:flex;flex-direction:column;gap:6px;margin-bottom:10px}\n.portable-row{display:flex;gap:8px;align-items:center}\n.portable-row input{border:1px solid #e2e8f0;border-radius:7px;padding:8px 10px;font-size:.87rem;color:#1e293b;outline:none;transition:border-color .15s,box-shadow .15s;background:#fff}\n.portable-row input:focus{border-color:#2563eb;box-shadow:0 0 0 3px rgba(37,99,235,.1)}\n.pt-name{flex:3}.pt-ver{flex:1.5}\n.pt-del{flex:none;background:none;border:1px solid #e2e8f0;border-radius:6px;padding:7px 11px;cursor:pointer;color:#94a3b8;font-size:.85rem;line-height:1;transition:all .15s}\n.pt-del:hover{background:#fef2f2;border-color:#fca5a5;color:#ef4444}\n#add-portable-btn{background:none;border:1.5px dashed #cbd5e1;border-radius:7px;padding:8px 16px;color:#64748b;cursor:pointer;font-size:.83rem;width:100%;transition:all .15s;margin-top:2px}\n#add-portable-btn:hover{border-color:#2563eb;color:#2563eb;background:#eff6ff}\n\n/* Tabs */\n.tab-bar{display:flex;gap:0;margin-bottom:-1px;position:relative;z-index:1;padding-left:1px}\n.tab-btn{background:#f8fafc;border:1px solid #e2e8f0;border-bottom:none;border-radius:10px 10px 0 0;padding:10px 22px;font-size:.88rem;font-weight:600;color:#64748b;cursor:pointer;margin-right:4px;transition:background .15s,color .15s;white-space:nowrap}\n.tab-btn:hover:not(.active){background:#eff6ff;color:#2563eb;border-color:#bfdbfe}\n.tab-btn.active{background:#fff;color:#1e3a5f}\n.tab-bar-bottom{margin-top:12px;padding-left:1px}\n.tab-bar-bottom .tab-btn{border-bottom:1px solid #e2e8f0;border-radius:0 0 10px 10px}\n.tab-panel{display:none;background:#fff;border:1px solid #e2e8f0;border-radius:0 12px 12px 12px;padding:22px 26px;margin-bottom:18px;box-shadow:0 1px 4px rgba(0,0,0,.08)}\n.tab-panel.active{display:block}\n.section-divider{border:none;border-top:1px solid #f1f5f9;margin:18px -26px}\n.tab-hint{font-size:.78rem;color:#64748b;margin-bottom:14px;line-height:1.5}\n/* Manual entry rows */\n#manual-list{display:flex;flex-direction:column;gap:6px;margin-bottom:10px}\n.manual-row{display:flex;gap:8px;align-items:center}\n.manual-row input{border:1px solid #e2e8f0;border-radius:7px;padding:8px 10px;font-size:.87rem;color:#1e293b;outline:none;transition:border-color .15s,box-shadow .15s;background:#fff}\n.manual-row input:focus{border-color:#2563eb;box-shadow:0 0 0 3px rgba(37,99,235,.1)}\n.mn-name{flex:3}.mn-ver{flex:1.5}\n.mn-del{flex:none;background:none;border:1px solid #e2e8f0;border-radius:6px;padding:7px 11px;cursor:pointer;color:#94a3b8;font-size:.85rem;line-height:1;transition:all .15s}\n.mn-del:hover{background:#fef2f2;border-color:#fca5a5;color:#ef4444}\n#add-manual-btn{background:none;border:1.5px dashed #cbd5e1;border-radius:7px;padding:8px 16px;color:#64748b;cursor:pointer;font-size:.83rem;width:100%;transition:all .15s;margin-top:2px}\n#add-manual-btn:hover{border-color:#2563eb;color:#2563eb;background:#eff6ff}\n\nfooter{text-align:center;padding:24px;font-size:.74rem;color:#94a3b8}\n</style>\n</head>\n<body>\n\n<header>\n  <h1>CVE Web Scanner</h1>\n  <p>上傳 scan.json &rarr; 查詢 NIST NVD CVE API &rarr; 檢視弱點報表 &nbsp;·&nbsp; 無需安裝 Node.js，零伺服器</p>\n</header>\n\n<main>\n\n<!-- Settings (shared: API key, severity, year, max CVEs) -->\n<div class=\"card\">\n  <div class=\"card-title\">⚙ 掃描設定（選填，設定會自動儲存）</div>\n  <div class=\"settings-grid\">\n    <div class=\"form-group\">\n      <label>NIST API Key</label>\n      <input type=\"password\" id=\"api-key\" placeholder=\"未填仍可運作，但速率較慢\">\n      <span class=\"hint\">無 Key：6.5 秒/次 &nbsp;|&nbsp; 有 Key：0.7 秒/次 &nbsp;&nbsp;<a href=\"https://nvd.nist.gov/developers/request-an-api-key\" target=\"_blank\">免費申請</a></span>\n    </div>\n    <div class=\"form-group\">\n      <label>最低嚴重度</label>\n      <select id=\"min-severity\">\n        <option value=\"LOW\">LOW（全部）</option>\n        <option value=\"MEDIUM\">MEDIUM</option>\n        <option value=\"HIGH\" selected>HIGH（預設）</option>\n        <option value=\"CRITICAL\">CRITICAL（僅最高）</option>\n      </select>\n    </div>\n    <div class=\"form-group\">\n      <label>CVE 最早年份</label>\n      <input type=\"number\" id=\"min-year\" placeholder=\"空白=當年−5（預設）\">\n      <span class=\"hint\">只顯示該年份後發佈的 CVE</span>\n    </div>\n    <div class=\"form-group\">\n      <label>每項軟體最多 CVE 筆數</label>\n      <input type=\"number\" id=\"max-cves\" value=\"50\" min=\"1\" max=\"2000\">\n      <span class=\"hint\">NVD 回傳順序為最新優先</span>\n    </div>\n  </div>\n</div>\n\n<!-- Tab navigation -->\n<div class=\"tab-bar\">\n  <button class=\"tab-btn active\" data-tab=\"file\">📁 檔案掃描(JSON)</button>\n  <button class=\"tab-btn\" data-tab=\"manual\">✏ 人工掃描</button>\n</div>\n\n<!-- Tab: File mode -->\n<div class=\"tab-panel active\" id=\"tab-file\">\n  <div class=\"card-title\"><span class=\"step-badge\">1</span> 上傳 scan.json</div>\n  <div id=\"drop-zone\">\n    <span class=\"dz-icon\">📂</span>\n    <div class=\"dz-label\">點擊選擇檔案，或將 scan.json 拖曳至此</div>\n    <div class=\"dz-sub\">由 cve-checker.js 或 findSW.ps1 在目標機器上產生的 JSON 掃描檔</div>\n  </div>\n  <input type=\"file\" id=\"file-input\" accept=\".json,application/json\">\n  <div id=\"file-info\"></div>\n  <div id=\"findsw-dl-hint\" style=\"display:none;margin-top:10px;font-size:.8rem;color:#64748b;background:#f8fafc;border-radius:7px;padding:9px 13px;border-left:3px solid #2563eb\">\n    還沒有 scan.json？先在目標 Windows 機器上執行 <strong>findSW.ps1</strong> 產生掃描檔，再上傳至此。\n    &nbsp;<span style=\"color:#64748b\">（請向系統維護人員索取 PS1 檔案掃描工具）</span>\n  </div>\n  <hr class=\"section-divider\">\n  <div class=\"card-title\" style=\"margin-top:4px\"><span class=\"step-badge\">2</span> 白名單（Publisher 關鍵字，逗號分隔）</div>\n  <div class=\"form-group\" style=\"margin-bottom:0\">\n    <input type=\"text\" id=\"whitelist\" placeholder=\"例：Microsoft,Apple,Google\">\n    <span class=\"hint\">不分大小寫，部分比對 Publisher 欄位；符合條件的軟體略過掃描</span>\n  </div>\n  <div id=\"portable-section\">\n  <hr class=\"section-divider\">\n  <div class=\"card-title\" style=\"margin-top:4px\"><span class=\"step-badge\">3</span> 免安裝軟體（Portable / 未登錄於 Registry）</div>\n  <div id=\"portable-list\"></div>\n  <button type=\"button\" id=\"add-portable-btn\">＋ 新增項目</button>\n  <p class=\"form-group\" style=\"margin-top:8px\"><span class=\"hint\">不受白名單過濾，直接納入掃描。版本號可選填，用於比對是否需要升級。</span></p>\n  </div>\n  <!-- File scan: progress & result -->\n  <div class=\"inner-section\" id=\"file-progress-card\" style=\"display:none\">\n    <div class=\"card-title\">掃描進度</div>\n    <div class=\"progress-bar-wrap\"><div class=\"progress-bar\" id=\"file-progress-bar\"></div></div>\n    <div class=\"progress-stats\" id=\"file-progress-stats\"></div>\n    <div class=\"progress-log\" id=\"file-progress-log\"></div>\n  </div>\n  <div class=\"inner-section\" id=\"file-result-card\" style=\"display:none\">\n    <div class=\"card-title\">✅ 掃描完成</div>\n    <div class=\"dl-row\">\n      <button id=\"file-open-report-btn\" class=\"dl-btn primary\">📄 在新分頁開啟報表</button>\n      <a id=\"file-dl-html\" class=\"dl-btn secondary\" download=\"result.html\">⬇ 下載報表 HTML</a>\n      <a id=\"file-dl-json\" class=\"dl-btn secondary\" download=\"result.json\">⬇ result.json</a>\n    </div>\n  </div>\n</div>\n\n<!-- Tab: Manual entry mode -->\n<div class=\"tab-panel\" id=\"tab-manual\">\n  <p class=\"tab-hint\">直接輸入軟體名稱與版本號，不需要 scan.json 檔案。版本號可選填，留空仍可查詢 CVE，但無法判斷是否需要升級。此模式不套用白名單過濾。</p>\n  <div id=\"manual-list\"></div>\n  <button type=\"button\" id=\"add-manual-btn\">＋ 新增軟體</button>\n  <!-- Manual scan: progress & result (no downloads) -->\n  <div class=\"inner-section\" id=\"manual-progress-card\" style=\"display:none\">\n    <div class=\"card-title\">掃描進度</div>\n    <div class=\"progress-bar-wrap\"><div class=\"progress-bar\" id=\"manual-progress-bar\"></div></div>\n    <div class=\"progress-stats\" id=\"manual-progress-stats\"></div>\n    <div class=\"progress-log\" id=\"manual-progress-log\"></div>\n  </div>\n  <div class=\"inner-section\" id=\"manual-result-card\" style=\"display:none\">\n    <div class=\"card-title\">✅ 掃描完成</div>\n    <div class=\"dl-row\">\n      <button id=\"manual-open-report-btn\" class=\"dl-btn primary\">📄 在新分頁開啟報表</button>\n    </div>\n  </div>\n</div>\n\n<!-- Action -->\n<div class=\"card\" id=\"action-card\">\n  <button id=\"scan-btn\" disabled>▶ 開始掃描</button>\n  <button id=\"cancel-btn\">■ 取消掃描</button>\n  <span id=\"scan-status\">請先上傳 scan.json</span>\n</div>\n\n<!-- Bottom tab navigation -->\n<div class=\"tab-bar tab-bar-bottom\">\n  <button class=\"tab-btn active\" data-tab=\"file\">📁 檔案掃描(JSON)</button>\n  <button class=\"tab-btn\" data-tab=\"manual\">✏ 人工掃描</button>\n</div>\n\n</main>\n<footer>CVE Web Scanner &nbsp;·&nbsp; Powered by <a href=\"https://nvd.nist.gov/developers/vulnerabilities\" target=\"_blank\">NIST NVD API 2.0</a><br>This product uses data from the NVD API but is not endorsed or certified by the NVD.</footer>\n\n<script>\n'use strict';\n\n// ─── Constants ────────────────────────────────────────────────────────────────\nconst NVD_CVE_BASE = window.__NVD_PROXY__ || 'https://services.nvd.nist.gov/rest/json/cves/2.0';\n\n\nconst SKIP_PATTERNS = [\n    /^Microsoft Visual C\\+\\+.*(Additional|Minimum) Runtime/i,\n    /^Microsoft Visual C\\+\\+.*x(64|86) (Additional|Minimum)/i,\n    /^Office \\d+ Click-to-Run (Extensibility|Licensing|Localization)/i,\n    /^Python 3\\.\\d+\\.\\d+ (Add to Path|Core Interpreter|Development Libraries|Documentation|Executables|pip Bootstrap|Standard Library|Tcl\\/Tk|Test Suite|Utility Scripts)/i,\n    /^Microsoft Visual C\\+\\+ v14 Redistributable/i,\n];\n\n// ─── Module state ─────────────────────────────────────────────────────────────\nlet scanData = null;\nlet abortController = null;\nconst tabBlobUrls = { file: [], manual: [] };\nlet activeTab = 'file';\n\n// ─── HTML escaping ────────────────────────────────────────────────────────────\nfunction esc(s) {\n    return (s == null ? '' : String(s))\n        .replace(/&/g, '&amp;').replace(/</g, '&lt;')\n        .replace(/>/g, '&gt;').replace(/\"/g, '&quot;')\n        .replace(/'/g, '&#39;');\n}\n\n// ─── Core logic (ported from cve-checker.js) ─────────────────────────────────\nfunction shouldSkip(name) {\n    return SKIP_PATTERNS.some(p => p.test(name));\n}\n\nfunction formatDateTime(iso) {\n    const d = new Date(iso);\n    const pad = n => String(n).padStart(2, '0');\n    return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;\n}\n\nfunction cleanProductName(name) {\n    return name\n        .replace(/\\s+\\d+[\\d.]*(\\.\\d+)*(\\s|$)/g, ' ')\n        .replace(/\\s*\\(.*?\\)\\s*/g, ' ')\n        .replace(/\\s+-\\s+[\\d.]+\\s*$/g, '')\n        .replace(/\\s+(x64|x86|32-bit|64-bit)(\\s|$)/gi, ' ')\n        .replace(/\\s+/g, ' ')\n        .trim();\n}\n\nfunction matchWhitelist(sw, whitelist) {\n    const publisher = (sw.publisher || '').toLowerCase();\n    for (const rule of whitelist) {\n        if (publisher.includes(rule.toLowerCase())) return rule;\n    }\n    return null;\n}\n\n\n// Shared CVE processing logic — single source of truth.\n// Used by: cve-checker.js, team-report.js (via require), web/web-client.html (via build.js injection).\n// No I/O, no fetch, no Node.js APIs — pure functions only.\n'use strict';\n\nconst SEVERITY_ORDER = ['NONE', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];\n\n// Compare version strings like \"1.2.3\", \"10.0.0.1\"\nfunction compareVersions(a, b) {\n    const parse = v => String(v).split('.').map(n => parseInt(n, 10) || 0);\n    const ap = parse(a), bp = parse(b);\n    const len = Math.max(ap.length, bp.length);\n    for (let i = 0; i < len; i++) {\n        const diff = (ap[i] || 0) - (bp[i] || 0);\n        if (diff !== 0) return diff;\n    }\n    return 0;\n}\n\n// Check if the installed version already satisfies the fix requirement\nfunction isSafeVersion(installed, rec) {\n    if (!installed || !rec) return false;\n    const cmp = compareVersions(installed, rec.version);\n    return rec.op === '>=' ? cmp >= 0 : cmp > 0;\n}\n\nfunction getCvss(cve) {\n    const m = cve.metrics || {};\n    const checks = [\n        ['cvssMetricV40', '4.0'],\n        ['cvssMetricV31', '3.1'],\n        ['cvssMetricV30', '3.0'],\n        ['cvssMetricV2',  '2.0'],\n    ];\n    for (const [key, ver] of checks) {\n        if (m[key]?.[0]) {\n            const entry = m[key][0];\n            const d = entry.cvssData;\n            const severity = (d.baseSeverity || entry.baseSeverity || 'NONE').toUpperCase();\n            return { score: d.baseScore, severity, version: ver };\n        }\n    }\n    return { score: 0, severity: 'NONE', version: 'N/A' };\n}\n\n// Collect ALL vendor+product pairs from CPE API results that match the searched name.\n// Returns an array ordered by match quality (best first). The caller uses [0] as the\n// primary cpeBase for version extraction/reporting, and the full array for relevance\n// checking (OR logic) so that multiple vendor naming conventions are all covered\n// (e.g. both putty:putty and simon_tatham:putty for \"PuTTY\").\n//\n// Pass 0: vendor alone contains all name words → highest confidence (e.g. putty:putty).\n// Pass 1: vendor+product combined contains all name words (e.g. apache:maven for \"apache maven\").\n// Pass 2: fallback — first name word appears in product (e.g. neo4j:neo4j for \"Neo4j Community Edition\").\n// Only considers application-type CPEs (part = 'a').\nfunction findAllCPEBases(products, nameWords) {\n    if (!nameWords.length || !products.length) return [];\n    const results = [];\n    const seen = new Set();\n\n    const add = (parts) => {\n        const key = `${parts[3]}:${parts[4]}`;\n        if (seen.has(key)) return;\n        seen.add(key);\n        results.push({ vendor: parts[3], product: parts[4] });\n    };\n\n    for (const { cpe } of products) {\n        const parts = cpe.cpeName.split(':');\n        if (parts.length < 5 || parts[2] !== 'a') continue;\n        const vendor = parts[3].replace(/[_:.]/g, ' ').toLowerCase();\n        if (nameWords.every(w => vendor.includes(w))) add(parts);\n    }\n    for (const { cpe } of products) {\n        const parts = cpe.cpeName.split(':');\n        if (parts.length < 5 || parts[2] !== 'a') continue;\n        const cpeStr = `${parts[3]} ${parts[4]}`.replace(/[_:.]/g, ' ').toLowerCase();\n        if (nameWords.every(w => cpeStr.includes(w))) add(parts);\n    }\n    if (results.length === 0) {\n        const firstWord = nameWords[0];\n        for (const { cpe } of products) {\n            const parts = cpe.cpeName.split(':');\n            if (parts.length < 5 || parts[2] !== 'a') continue;\n            const product = parts[4].replace(/[_:.]/g, ' ').toLowerCase();\n            if (product.includes(firstWord)) add(parts);\n        }\n    }\n    return results;\n}\n\n// Check if a CVE's configurations contain a CPE matching ANY of the given bases.\n// Uses OR logic so that multiple vendor naming conventions are all covered.\n// More precise than cveRelevanceCheck — avoids false positives such as Jenkins CVEs\n// that only mention Maven in their description text.\n// Returns true (match), false (no CPE matches), or null (no CPE data).\nfunction cveMatchesCPEBase(cve, bases) {\n    const patterns = bases.map(b => `:${b.vendor}:${b.product}:`.toLowerCase());\n    const configs = cve.configurations || [];\n    if (!configs.length) return null;\n    let hasCPEs = false;\n    for (const config of configs) {\n        for (const node of (config.nodes || [])) {\n            for (const m of (node.cpeMatch || [])) {\n                if (!m.criteria) continue;\n                hasCPEs = true;\n                if (!m.vulnerable) continue; // skip platform dependencies (vulnerable: false)\n                const criteria = m.criteria.toLowerCase();\n                if (patterns.some(p => criteria.includes(p))) return true;\n            }\n        }\n    }\n    return hasCPEs ? false : null;\n}\n\n// Check whether a CVE's CPE entries actually match the searched product name.\n// Returns true (match), false (mismatch), or null (no CPE data — can't tell).\nfunction cveRelevanceCheck(cve, searchName) {\n    const configs = cve.configurations || [];\n    if (!configs.length) return null;\n\n    const words = searchName.toLowerCase()\n        .replace(/[^a-z0-9]/g, ' ').split(/\\s+/).filter(w => w.length >= 2);\n    if (!words.length) return null;\n\n    const cpeLines = [];\n    for (const config of configs) {\n        for (const node of (config.nodes || [])) {\n            for (const m of (node.cpeMatch || [])) {\n                if (m.criteria) cpeLines.push(m.criteria.toLowerCase().replace(/[_:]/g, ' '));\n            }\n        }\n    }\n    if (!cpeLines.length) return null;\n\n    const cpeText = cpeLines.join(' ');\n    return words.every(w => cpeText.includes(w));\n}\n\n// Check if a CVE only lists exact affected versions (no ranges).\n// Returns null  → has version ranges or can't determine → skip this check\n// Returns { affected: true }                 → installed version is in exact affected list\n// Returns { affected: false, versions: [] }  → not in exact list → CVE doesn't apply\nfunction cveExactVersionCheck(installedVersion, cve, searchName, cpeBase) {\n    let words;\n    if (cpeBase) {\n        const raw = `${cpeBase.vendor} ${cpeBase.product}`.replace(/_/g, ' ').toLowerCase();\n        words = [...new Set(raw.split(/\\s+/).filter(w => w.length >= 2))];\n    } else {\n        words = searchName\n            ? searchName.toLowerCase().replace(/[^a-z0-9]/g, ' ').split(/\\s+/).filter(w => w.length >= 2)\n            : [];\n    }\n\n    const matchingEntries = [];\n    for (const config of (cve.configurations || [])) {\n        for (const node of (config.nodes || [])) {\n            for (const match of (node.cpeMatch || [])) {\n                if (!match.vulnerable) continue;\n                if (words.length && match.criteria) {\n                    const cpe = match.criteria.toLowerCase().replace(/[_:]/g, ' ');\n                    if (!words.every(w => cpe.includes(w))) continue;\n                }\n                matchingEntries.push(match);\n            }\n        }\n    }\n\n    if (matchingEntries.length === 0) return null;\n\n    // If any entry has a version range → existing extractFixedVersion handles it\n    const hasRange = matchingEntries.some(m =>\n        m.versionEndExcluding || m.versionEndIncluding ||\n        m.versionStartIncluding || m.versionStartExcluding\n    );\n    if (hasRange) return null;\n\n    // All entries are exact-version CPEs — extract version from field 5 of CPE 2.3\n    // cpe:2.3:a:vendor:product:VERSION:...\n    const affectedVersions = matchingEntries\n        .map(m => (m.criteria || '').split(':')[5] || '')\n        .filter(v => v && v !== '*' && v !== '-');\n\n    if (affectedVersions.length === 0) return null; // wildcard version → can't determine\n\n    if (!installedVersion || installedVersion === '?') return null;\n\n    const isAffected = affectedVersions.some(v => compareVersions(installedVersion, v) === 0);\n    return isAffected ? { affected: true } : { affected: false, versions: affectedVersions };\n}\n\n// Build the CPE word filter shared by extractFixedVersion / isVersionInAnyRange.\nfunction _cpeWords(searchName, cpeBase) {\n    if (cpeBase) {\n        const raw = `${cpeBase.vendor} ${cpeBase.product}`.replace(/_/g, ' ').toLowerCase();\n        return [...new Set(raw.split(/\\s+/).filter(w => w.length >= 2))];\n    }\n    return searchName\n        ? searchName.toLowerCase().replace(/[^a-z0-9]/g, ' ').split(/\\s+/).filter(w => w.length >= 2)\n        : [];\n}\n\n// Check whether a single cpeMatch entry's range includes installedVersion.\nfunction _matchInRange(match, ver) {\n    if (match.versionStartIncluding && compareVersions(ver, match.versionStartIncluding) < 0)  return false;\n    if (match.versionStartExcluding && compareVersions(ver, match.versionStartExcluding) <= 0) return false;\n    if (match.versionEndExcluding   && compareVersions(ver, match.versionEndExcluding)   >= 0) return false;\n    if (match.versionEndIncluding   && compareVersions(ver, match.versionEndIncluding)   > 0)  return false;\n    return true;\n}\n\n// Check whether installedVersion falls within any of the CVE's vulnerable version ranges.\n// Returns true  → in at least one affected range (CVE applies)\n// Returns false → outside every range (CVE does not apply to this install)\n// Returns null  → no usable range data; cannot determine\nfunction isVersionInAnyRange(installedVersion, cve, searchName, cpeBase) {\n    if (!installedVersion || installedVersion === '?') return null;\n    const words = _cpeWords(searchName, cpeBase);\n    let foundRangeEntry = false;\n    for (const config of (cve.configurations || [])) {\n        for (const node of (config.nodes || [])) {\n            for (const match of (node.cpeMatch || [])) {\n                if (!match.vulnerable) continue;\n                if (words.length && match.criteria) {\n                    const cpe = match.criteria.toLowerCase().replace(/[_:]/g, ' ');\n                    if (!words.every(w => cpe.includes(w))) continue;\n                }\n                const hasRange = match.versionEndExcluding || match.versionEndIncluding ||\n                                 match.versionStartIncluding || match.versionStartExcluding;\n                if (!hasRange) continue;\n                foundRangeEntry = true;\n                if (_matchInRange(match, installedVersion)) return true;\n            }\n        }\n    }\n    return foundRangeEntry ? false : null;\n}\n\n// Return the fix version for the range that affects installedVersion (branch-aware).\n// When installedVersion is null, falls back to global maximum (legacy behaviour).\n// searchName filters CPEs to only those matching the searched product, avoiding version\n// numbers from unrelated configurations (e.g. Oracle products in an Apache Maven CVE).\nfunction extractFixedVersion(cve, searchName, cpeBase = null, installedVersion = null) {\n    const words = _cpeWords(searchName, cpeBase);\n    let best = null;\n    for (const config of (cve.configurations || [])) {\n        for (const node of (config.nodes || [])) {\n            for (const match of (node.cpeMatch || [])) {\n                if (!match.vulnerable) continue;\n                if (words.length && match.criteria) {\n                    const cpe = match.criteria.toLowerCase().replace(/[_:]/g, ' ');\n                    if (!words.every(w => cpe.includes(w))) continue;\n                }\n                // When the installed version is known, only consider the range it falls in so\n                // we return the branch-specific fix (e.g. 24.13.0) rather than the global max\n                // across all branches (e.g. 25.3.0 for a CVE that also affects 25.x).\n                if (installedVersion && installedVersion !== '?') {\n                    const hasRange = match.versionEndExcluding || match.versionEndIncluding ||\n                                     match.versionStartIncluding || match.versionStartExcluding;\n                    if (hasRange && !_matchInRange(match, installedVersion)) continue;\n                }\n                let candidate = null;\n                if (match.versionEndExcluding) {\n                    candidate = { version: match.versionEndExcluding, op: '>=' };\n                } else if (match.versionEndIncluding) {\n                    candidate = { version: match.versionEndIncluding, op: '>' };\n                }\n                if (candidate && (!best || compareVersions(candidate.version, best.version) > 0)) {\n                    best = candidate;\n                }\n            }\n        }\n    }\n    return best; // null if no fix version info available\n}\n\n// Find the highest recommended version across all CVEs for a software.\n// Pass installedVersion so each per-CVE fix reflects the user's branch, not the global max.\nfunction getRecommendedVersion(cves, searchName, cpeBase = null, installedVersion = null) {\n    let best = null;\n    for (const v of cves) {\n        const fix = extractFixedVersion(v.cve, searchName, cpeBase, installedVersion);\n        if (fix && (!best || compareVersions(fix.version, best.version) > 0)) {\n            best = fix;\n        }\n    }\n    return best;\n}\n\n// Return ALL affected version ranges for a CVE, sorted by start version ascending.\n// Each entry: { from, fromOp, to, toOp }\n//   from/fromOp: versionStartIncluding (>=) or versionStartExcluding (>), null if none\n//   to/toOp:     versionEndExcluding   (>=) or versionEndIncluding   (>)\n// Only entries with a fix version (to) are included. Used for the HTML report range table.\nfunction extractAllRanges(cve, searchName, cpeBase) {\n    const words = _cpeWords(searchName, cpeBase);\n    const ranges = [];\n    const seen = new Set();\n    for (const config of (cve.configurations || [])) {\n        for (const node of (config.nodes || [])) {\n            for (const match of (node.cpeMatch || [])) {\n                if (!match.vulnerable) continue;\n                if (words.length && match.criteria) {\n                    const cpe = match.criteria.toLowerCase().replace(/[_:]/g, ' ');\n                    if (!words.every(w => cpe.includes(w))) continue;\n                }\n                if (!match.versionEndExcluding && !match.versionEndIncluding) continue;\n                const from    = match.versionStartIncluding || match.versionStartExcluding || null;\n                const fromOp  = match.versionStartExcluding ? '>' : (from ? '>=' : null);\n                const to      = match.versionEndExcluding   || match.versionEndIncluding;\n                const toOp    = match.versionEndExcluding   ? '>=' : '>';\n                const key = `${from ?? ''}:${toOp}${to}`;\n                if (seen.has(key)) continue;\n                seen.add(key);\n                ranges.push({ from, fromOp, to, toOp });\n            }\n        }\n    }\n    ranges.sort((a, b) => {\n        if (!a.from && !b.from) return 0;\n        if (!a.from) return -1;\n        if (!b.from) return 1;\n        return compareVersions(a.from, b.from);\n    });\n    return ranges;\n}\n\nif (typeof module !== 'undefined') {\n    module.exports = {\n        SEVERITY_ORDER,\n        compareVersions,\n        isSafeVersion,\n        getCvss,\n        findAllCPEBases,\n        cveMatchesCPEBase,\n        cveRelevanceCheck,\n        cveExactVersionCheck,\n        _cpeWords,\n        _matchInRange,\n        isVersionInAnyRange,\n        extractFixedVersion,\n        getRecommendedVersion,\n        extractAllRanges,\n    };\n}\n\n\n\nconst MAX_FETCH_RETRIES   = 10;   // total retry attempts per software item\nconst FETCH_RETRY_DELAY_MS = 5000; // ms between retries (except 429 rate-limit)\n\nasync function nvdFetch(url, apiKey, signal, retries = MAX_FETCH_RETRIES, onRetry = null) {\n    const headers = {};\n    // When proxied through local server, API key is added server-side to avoid CORS preflight\n    if (apiKey && !window.__NVD_PROXY__) headers['apiKey'] = apiKey;\n    const attempt = MAX_FETCH_RETRIES - retries + 1;\n    const delaySec = FETCH_RETRY_DELAY_MS / 1000;\n    let res;\n    try {\n        // 45 s per-request browser timeout: longer than proxy's 30 s NVD timeout so the\n        // proxy always responds first under normal conditions, but catches cases where the\n        // proxy hangs (e.g. 4 consecutive NVD timeouts = ~124 s wait without this guard).\n        const perReqSignal = typeof AbortSignal.any === 'function'\n            ? AbortSignal.any([signal, AbortSignal.timeout(45000)])\n            : signal;\n        res = await fetch(url, { headers, signal: perReqSignal });\n    } catch (err) {\n        if (err.name === 'AbortError' && signal.aborted) throw err; // user cancelled\n        // TimeoutError (45 s browser guard) or network error — retry\n        if (retries > 0) {\n            const isTimeout = err.name === 'TimeoutError' || (err.name === 'AbortError' && !signal.aborted);\n            onRetry?.(isTimeout\n                ? `請求逾時，${delaySec} 秒後重試 ${attempt}/${MAX_FETCH_RETRIES}…`\n                : `連線失敗 [${err.name}]，${delaySec} 秒後重試 ${attempt}/${MAX_FETCH_RETRIES}…`);\n            await sleep(FETCH_RETRY_DELAY_MS, signal);\n            return nvdFetch(url, apiKey, signal, retries - 1, onRetry);\n        }\n        throw err;\n    }\n    if (res.ok) {\n        try {\n            return await res.json();\n        } catch (_) {\n            // Truncated response (proxy lost NVD connection mid-stream) — retry\n            if (retries > 0) {\n                onRetry?.(`回應不完整，${delaySec} 秒後重試 ${attempt}/${MAX_FETCH_RETRIES}…`);\n                await sleep(FETCH_RETRY_DELAY_MS, signal);\n                return nvdFetch(url, apiKey, signal, retries - 1, onRetry);\n            }\n            throw new Error('NVD API 回應不完整（連線中斷）');\n        }\n    }\n    if (res.status === 429 && retries > 0) {\n        onRetry?.(`速率限制 (429)，15 秒後重試 ${attempt}/${MAX_FETCH_RETRIES}…`);\n        await sleep(15000, signal);\n        return nvdFetch(url, apiKey, signal, retries - 1, onRetry);\n    }\n    // 502/503/504 = proxy error or NVD timeout; 403 = NVD rejected — all worth one retry\n    if ((res.status === 502 || res.status === 503 || res.status === 504 || res.status === 403) && retries > 0) {\n        onRetry?.(`HTTP ${res.status}，${delaySec} 秒後重試 ${attempt}/${MAX_FETCH_RETRIES}…`);\n        await sleep(FETCH_RETRY_DELAY_MS, signal);\n        return nvdFetch(url, apiKey, signal, retries - 1, onRetry);\n    }\n    throw new Error(`NVD API HTTP ${res.status}`);\n}\n\nasync function searchCVEs(keyword, apiKey, maxCves, minYear, signal, onRetry) {\n    const params = new URLSearchParams({ keywordSearch: keyword, resultsPerPage: String(maxCves), noRejected: '' });\n    return nvdFetch(`${NVD_CVE_BASE}?${params}`, apiKey, signal, MAX_FETCH_RETRIES, onRetry);\n}\n\n\n// Shared HTML report generator — single source of truth.\n// Used by: cve-checker.js (via require), web/web-client.html (via build.js injection).\n// Pure function: takes a report object, returns an HTML string. No I/O.\n'use strict';\n\n// In Node.js: isSafeVersion comes from cve-logic. In browser: already in scope from @@CVE_LOGIC@@ injection.\nconst _isSafeVersion =\n    typeof isSafeVersion !== 'undefined'\n        ? isSafeVersion\n        : require('./cve-logic').isSafeVersion;\n\nfunction _formatDateTime(iso) {\n    const d = new Date(iso);\n    const pad = n => String(n).padStart(2, '0');\n    return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;\n}\n\nfunction buildHTMLReport(report) {\n    const esc = s => (s == null ? '' : String(s))\n        .replace(/&/g, '&amp;').replace(/</g, '&lt;')\n        .replace(/>/g, '&gt;').replace(/\"/g, '&quot;')\n        .replace(/'/g, '&#39;');\n\n    const SEV_COLOR = { CRITICAL: '#dc2626', HIGH: '#ea580c', MEDIUM: '#d97706', LOW: '#2563eb' };\n    const badge = (sev, score) =>\n        `<span class=\"badge\" style=\"background:${SEV_COLOR[sev]||'#6b7280'}\">${esc(sev)}${score !== '' ? ' '+score : ''}</span>`;\n\n    const hasUnfixedCVE = r => (r.cves || []).some(v => !v.fixedVersion);\n\n    // 已修正：有明確修復版、目前版本已達要求、所有 CVE 均有 fix 資訊 → 列入獨立稽核區塊\n    const fixedResults  = report.results.filter(r =>\n        r.recommendedVersion && _isSafeVersion(r.software.version, r.recommendedVersion) && !hasUnfixedCVE(r)\n    );\n    // 需行動：需升級 ✗ 或無法確定 ? → 列入主摘要與 CVE 詳細資訊\n    const actionResults = report.results.filter(r =>\n        !r.recommendedVersion || !_isSafeVersion(r.software.version, r.recommendedVersion) || hasUnfixedCVE(r)\n    );\n\n    const needUpgrade  = actionResults.filter(r => r.recommendedVersion && !_isSafeVersion(r.software.version, r.recommendedVersion)).length;\n    const noRecCount   = actionResults.filter(r => !r.recommendedVersion || hasUnfixedCVE(r)).length;\n    const alreadySafe  = fixedResults.length;\n    const cleanCount   = (report.cleanResults || []).length;\n    const scanDateStr  = (report.generatedAt || '').substring(0, 10).replace(/-/g, '/');\n    const minYearLabel = report.minYear ? `${report.minYear}/01/01~${scanDateStr}` : '不限';\n\n    // Whitelisted section\n    const wlGroups = {};\n    for (const sw of (report.whitelisted || [])) (wlGroups[sw.matchedRule] ??= []).push(sw);\n    const wlHTML = (report.whitelisted || []).length === 0 ? '' : `\n  <section id=\"whitelisted\">\n    <h2>白名單跳過的軟體（${report.whitelisted.length} 筆，未進行掃描）</h2>\n    <p class=\"sec-note\">以下軟體因 Publisher 符合白名單設定而略過，未查詢 NIST NVD。</p>\n    ${Object.entries(wlGroups).map(([rule, list]) => `\n    <div class=\"wl-group\"><div class=\"wl-rule\">規則：${esc(rule)}</div>\n    <table><thead><tr><th>Software</th><th>Version</th><th>Publisher</th></tr></thead>\n    <tbody>${list.map(sw => `<tr><td>${esc(sw.name)}</td><td>${esc(sw.version)}</td><td>${esc(sw.publisher)}</td></tr>`).join('')}</tbody></table></div>`).join('')}\n  </section>`;\n\n    const patternHTML = (report.skippedByPattern || []).length === 0 ? '' : `\n  <section id=\"skipped-pattern\">\n    <h2>子元件跳過的軟體（${report.skippedByPattern.length} 筆，未進行掃描）</h2>\n    <p class=\"sec-note\">以下軟體符合內建 SKIP_PATTERNS 規則（VC++ Runtime 子元件、Office Click-to-Run 元件、Python 子安裝項），其弱點已由對應的主程式條目代表，故略過。</p>\n    <table><thead><tr><th>Software</th><th>Version</th><th>Publisher</th></tr></thead>\n    <tbody>${report.skippedByPattern.map(sw => `<tr><td>${esc(sw.name)}</td><td>${esc(sw.version)}</td><td>${esc(sw.publisher)}</td></tr>`).join('')}</tbody></table>\n  </section>`;\n\n    const dedupHTML = (report.skippedByDedup || []).length === 0 ? '' : `\n  <section id=\"skipped-dedup\">\n    <h2>重複去除的軟體（${report.skippedByDedup.length} 筆，未進行掃描）</h2>\n    <p class=\"sec-note\">以下軟體在去除版號後與另一條目名稱相同，已由較早出現的條目代表，故略過重複查詢。</p>\n    <table><thead><tr><th>Software</th><th>Version</th><th>Publisher</th><th>合併為</th></tr></thead>\n    <tbody>${report.skippedByDedup.map(sw => `<tr><td>${esc(sw.name)}</td><td>${esc(sw.version)}</td><td>${esc(sw.publisher)}</td><td style=\"font-size:.78rem;color:#6b7280\">${esc(sw.mergedAs)}</td></tr>`).join('')}</tbody></table>\n  </section>`;\n\n    // 主摘要表：只顯示「需行動」項目（✗ 升級 / ? 確認），已修正者移至獨立稽核區\n    const affectedRows = actionResults.map(r => {\n        const { software, recommendedVersion, cves } = r;\n        const unfixedCVE = (cves || []).some(v => !v.fixedVersion);\n        let recTd, statusTd;\n        if (recommendedVersion) {\n            recTd = `${recommendedVersion.op === '>=' ? '≥' : '>'} ${esc(recommendedVersion.version)}`;\n            statusTd = !_isSafeVersion(software.version, recommendedVersion)\n                ? `<td class=\"st danger\">✗ 需要升級</td>`\n                : `<td class=\"st warn\">? 請手動確認</td>`;\n        } else {\n            recTd = '—';\n            statusTd = `<td class=\"st warn\">? 請手動確認</td>`;\n        }\n        return `<tr><td>${esc(software.name)}</td><td>${esc(software.publisher||'—')}</td><td>${esc(software.version||'?')}</td><td>${recTd}</td>${statusTd}</tr>`;\n    }).join('\\n');\n\n    const cleanRows = (report.cleanResults || []).map(r =>\n        `<tr><td>${esc(r.software.name)}</td><td>${esc(r.software.publisher||'—')}</td><td>${esc(r.software.version||'?')}</td><td>—</td><td class=\"st safe\">✓ 無弱點</td></tr>`\n    ).join('\\n');\n\n    const tableRows = affectedRows + (cleanRows\n        ? `\\n<tr class=\"sep-row\"><td colspan=\"5\" style=\"background:#f0fdf4;color:#16a34a;font-size:.78rem;font-weight:600;padding:5px 12px\">── 以下軟體掃描後無發現 ${esc(report.minSeverity)} 以上弱點 ──</td></tr>\\n` + cleanRows\n        : '');\n\n    // CVE 詳細資訊：只列「需行動」項目\n    const detailsHTML = actionResults.map(r => {\n        const { software, cves, recommendedVersion, searchName } = r;\n        const installed = software.version || '?';\n        const topSev = cves[0]?.severity || 'NONE';\n\n        let recHtml;\n        if (recommendedVersion) {\n            recHtml = !_isSafeVersion(installed, recommendedVersion)\n                ? `<div class=\"rec danger\">✗ 建議升級至 ${recommendedVersion.op === '>=' ? '≥' : '>'} ${esc(recommendedVersion.version)}（目前：${esc(installed)}）</div>`\n                : `<div class=\"rec warn\">? 部分 CVE 無版本修復資訊，請手動確認</div>`;\n        } else {\n            recHtml = `<div class=\"rec warn\">? 無版本修復資訊，請查閱各 CVE 連結</div>`;\n        }\n\n        const cveRows = cves.map(cve => {\n            let fixHtml = '';\n            if (cve.affectedRanges && cve.affectedRanges.length > 0) {\n                const rows = cve.affectedRanges.map(rv => {\n                    const fromStr = rv.from ? `${rv.fromOp === '>' ? '>' : '≥'} ${esc(rv.from)}` : '＊';\n                    const toStr   = `${rv.toOp === '>=' ? '≥' : '>'} ${esc(rv.to)}`;\n                    return `<tr><td class=\"r-from\">${fromStr}</td><td class=\"r-arr\">→</td><td class=\"r-to\">${toStr}</td></tr>`;\n                }).join('');\n                fixHtml = `<div class=\"fix\">✓ 安全版本（各分支）：<table class=\"ranges\">${rows}</table></div>`;\n            } else if (cve.fixedVersion) {\n                fixHtml = `<div class=\"fix\">✓ 安全版本：${cve.fixedVersion.op === '>=' ? '≥' : '>'} ${esc(cve.fixedVersion.version)}</div>`;\n            }\n            const pendingHtml = cve.pendingNvdAnalysis\n                ? `<div class=\"pending-nvd\">⚠ NVD 尚未完成分析（無 CPE 資料），請至 <a href=\"${esc(cve.url)}\" target=\"_blank\">NVD 頁面</a> 手動確認是否影響已安裝版本</div>`\n                : '';\n            return `\n      <div class=\"cve${cve.pendingNvdAnalysis ? ' cve-pending' : ''}\">\n        <div class=\"cve-hd\">\n          <a href=\"${esc(cve.url)}\" target=\"_blank\" class=\"cve-id\">${esc(cve.id)}</a>\n          ${badge(cve.severity, cve.cvssScore)}\n          <span class=\"cvss-v\">CVSS${esc(cve.cvssVersion||'')}</span>\n          <span class=\"pub\">${(cve.published||'').substring(0,10)}</span>\n          ${cve.pendingNvdAnalysis ? '<span class=\"nvd-pending-tag\">⚠ NVD 分析中</span>' : ''}\n        </div>\n        <p class=\"desc\">${esc(cve.description||'')}</p>\n        ${fixHtml}${pendingHtml}\n      </div>`;\n        }).join('');\n\n        return `\n    <details>\n      <summary>\n        <span class=\"sw-name\">${esc(software.name)}</span>\n        <span class=\"sw-ver\">v${esc(installed)}</span>\n        ${badge(topSev, '')}\n        <span class=\"cnt\">${cves.length} CVE${cves.length > 1 ? 's' : ''}</span>\n      </summary>\n      <div class=\"sw-meta\">Publisher: ${esc(software.publisher||'N/A')} &nbsp;|&nbsp; Search: \"${esc(searchName)}\"</div>\n      <div class=\"cve-list\">${cveRows}</div>\n      ${recHtml}\n    </details>`;\n    }).join('\\n');\n\n    // 已修正弱點稽核區：有 CVE 但版本已達修復要求，僅供參考不需行動\n    const fixedDetailsHTML = fixedResults.length === 0 ? '' : fixedResults.map(r => {\n        const { software, cves, recommendedVersion, searchName } = r;\n        const installed = software.version || '?';\n        const topSev = cves[0]?.severity || 'NONE';\n        const recVer = `${recommendedVersion.op === '>=' ? '≥' : '>'} ${esc(recommendedVersion.version)}`;\n\n        const cveRows = cves.map(cve => {\n            let fixHtml = '';\n            if (cve.affectedRanges && cve.affectedRanges.length > 0) {\n                const rows = cve.affectedRanges.map(rv => {\n                    const fromStr = rv.from ? `${rv.fromOp === '>' ? '>' : '≥'} ${esc(rv.from)}` : '＊';\n                    const toStr   = `${rv.toOp === '>=' ? '≥' : '>'} ${esc(rv.to)}`;\n                    return `<tr><td class=\"r-from\">${fromStr}</td><td class=\"r-arr\">→</td><td class=\"r-to\">${toStr}</td></tr>`;\n                }).join('');\n                fixHtml = `<div class=\"fix\">✓ 安全版本（各分支）：<table class=\"ranges\">${rows}</table></div>`;\n            } else if (cve.fixedVersion) {\n                fixHtml = `<div class=\"fix\">✓ 安全版本：${cve.fixedVersion.op === '>=' ? '≥' : '>'} ${esc(cve.fixedVersion.version)}</div>`;\n            }\n            return `\n      <div class=\"cve\">\n        <div class=\"cve-hd\">\n          <a href=\"${esc(cve.url)}\" target=\"_blank\" class=\"cve-id\">${esc(cve.id)}</a>\n          ${badge(cve.severity, cve.cvssScore)}\n          <span class=\"cvss-v\">CVSS${esc(cve.cvssVersion||'')}</span>\n          <span class=\"pub\">${(cve.published||'').substring(0,10)}</span>\n        </div>\n        <p class=\"desc\">${esc(cve.description||'')}</p>\n        ${fixHtml}\n      </div>`;\n        }).join('');\n\n        return `\n    <details class=\"details-fixed\">\n      <summary>\n        <span class=\"sw-name\">${esc(software.name)}</span>\n        <span class=\"sw-ver\">v${esc(installed)}</span>\n        ${badge(topSev, '')}\n        <span class=\"fixed-tag\">✓ 已修正</span>\n        <span class=\"cnt\">${cves.length} CVE${cves.length > 1 ? 's' : ''}</span>\n      </summary>\n      <div class=\"sw-meta\">Publisher: ${esc(software.publisher||'N/A')} &nbsp;|&nbsp; Search: \"${esc(searchName)}\" &nbsp;|&nbsp; 最低安全版本：${recVer}</div>\n      <div class=\"cve-list\">${cveRows}</div>\n      <div class=\"rec safe\">✓ 目前版本 (${esc(installed)}) 已達修復要求 ${recVer}，無需行動</div>\n    </details>`;\n    }).join('\\n');\n\n    const fixedSection = fixedResults.length === 0 ? '' : `\n  <section id=\"fixed-cves\">\n    <h2>✓ 已修正的已知弱點（${fixedResults.length} 套件，目前版本已達修復要求，點擊展開）</h2>\n    <p class=\"sec-note\">以下軟體在 NVD 中有已知 CVE 紀錄，但目前安裝版本符合或超過最低安全版本要求，<strong>無需採取行動</strong>。列出此紀錄供稽核參考，確認掃描確有執行。</p>\n    ${fixedDetailsHTML}\n  </section>`;\n\n    return `<!DOCTYPE html>\n<html lang=\"zh-TW\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>CVE Report — ${esc(report.generatedAt.substring(0,10))}</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#f3f4f6;color:#1f2937;line-height:1.5}\na{color:#2563eb;text-decoration:none}a:hover{text-decoration:underline}\nheader{background:#1e3a5f;color:#fff;padding:24px 32px}\nheader h1{font-size:1.5rem;font-weight:700;margin-bottom:6px}\n.meta{font-size:.83rem;opacity:.8;margin-bottom:16px}\n.dash{display:flex;align-items:stretch;gap:0;margin-top:16px;flex-wrap:wrap;gap:2px}\n.dash-grp{display:flex;flex-direction:column;gap:5px;padding:0 18px}\n.dash-grp:first-child{padding-left:0}\n.dash-grp-lbl{font-size:.58rem;text-transform:uppercase;letter-spacing:.12em;opacity:.4;margin-bottom:1px}\n.dash-cards{display:flex;align-items:center;gap:4px}\n.dash-sep{width:1px;background:rgba(255,255,255,.16);margin:0 4px;align-self:stretch;flex-shrink:0}\n.darr{font-size:.65rem;opacity:.3;flex-shrink:0;padding:0 2px}\n.dc{border-radius:10px;padding:18px 24px;text-align:center;min-width:100px;flex-shrink:0}\n.dc .n{font-size:2.8rem;font-weight:800;line-height:1;letter-spacing:-.03em}\n.dc .l{font-size:.69rem;opacity:.72;margin-top:8px;white-space:nowrap}\n.dc .s{font-size:.62rem;opacity:.48;margin-top:3px}\n.dc.tot{background:rgba(255,255,255,.16)}.dc.tot .n{color:#f1f5f9}\n.dc.skip{background:rgba(148,163,184,.14)}.dc.skip .n{color:#94a3b8}\n.dc.scan{background:rgba(59,130,246,.22)}.dc.scan .n{color:#93c5fd}\n.dc.ok{background:rgba(34,197,94,.18)}.dc.ok .n{color:#86efac}\n.dc.hi{background:rgba(239,68,68,.22)}.dc.hi .n{color:#fca5a5}\n.dc.neu{background:rgba(234,179,8,.16)}.dc.neu .n{color:#fde68a}\nmain{max-width:1100px;margin:24px auto;padding:0 16px}\nsection{background:#fff;border-radius:10px;padding:20px 24px;margin-bottom:20px;box-shadow:0 1px 3px rgba(0,0,0,.08)}\nh2{font-size:1rem;font-weight:700;margin-bottom:14px;color:#1e3a5f;border-bottom:2px solid #e5e7eb;padding-bottom:8px}\n#fixed-cves h2{color:#166534;border-bottom-color:#bbf7d0}\n.sec-note{font-size:.85rem;color:#6b7280;margin-bottom:12px}\ntable{width:100%;border-collapse:collapse;font-size:.875rem}\nth{background:#f9fafb;text-align:left;padding:8px 12px;font-size:.75rem;text-transform:uppercase;letter-spacing:.04em;color:#6b7280;border-bottom:2px solid #e5e7eb}\ntd{padding:8px 12px;border-bottom:1px solid #f3f4f6}\ntr:last-child td{border-bottom:none}tr:hover td{background:#fafafa}\n.st{font-weight:700;font-size:.85rem}.st.safe{color:#16a34a}.st.danger{color:#dc2626}.st.warn{color:#d97706}\ndetails{border:1px solid #e5e7eb;border-radius:8px;margin-bottom:8px;overflow:hidden}\ndetails.details-fixed{border-color:#bbf7d0}\nsummary{display:flex;align-items:center;gap:8px;padding:11px 16px;cursor:pointer;background:#f9fafb;list-style:none;flex-wrap:wrap;user-select:none}\ndetails.details-fixed>summary{background:#f0fdf4}\nsummary::-webkit-details-marker{display:none}\nsummary::before{content:'▶';font-size:.65rem;color:#9ca3af;transition:transform .15s;flex-shrink:0}\ndetails[open]>summary::before{transform:rotate(90deg)}\nsummary:hover{background:#f0f0f0}\ndetails.details-fixed>summary:hover{background:#dcfce7}\n.sw-name{font-weight:600;font-size:.93rem;flex:1}\n.sw-ver{color:#6b7280;font-size:.82rem}\n.cnt{color:#6b7280;font-size:.78rem;margin-left:auto}\n.fixed-tag{font-size:.75rem;font-weight:700;color:#166534;background:#dcfce7;border:1px solid #86efac;border-radius:4px;padding:1px 7px;white-space:nowrap}\n.sw-meta{padding:5px 16px;font-size:.78rem;color:#9ca3af}\n.sw-cpe{font-size:.7rem;color:#9ca3af;font-family:monospace;margin-top:2px}\n.badge{display:inline-block;padding:2px 7px;border-radius:4px;color:#fff;font-size:.73rem;font-weight:700;white-space:nowrap}\n.cve-list{padding:8px 16px 4px}\n.cve{background:#f9fafb;border-radius:6px;padding:9px 13px;margin-bottom:7px}\n.cve-pending{background:#fffbeb;border-left:3px solid #d97706}\n.cve-hd{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-bottom:3px}\n.cve-id{font-weight:700;font-family:monospace;font-size:.88rem;color:#1e3a5f}\n.cvss-v{font-size:.72rem;color:#9ca3af}\n.pub{font-size:.72rem;color:#9ca3af;margin-left:auto}\n.nvd-pending-tag{font-size:.7rem;font-weight:600;color:#92400e;background:#fef3c7;border:1px solid #fcd34d;border-radius:3px;padding:1px 5px;white-space:nowrap}\n.desc{font-size:.82rem;color:#4b5563;margin:3px 0}\n.fix{font-size:.78rem;color:#16a34a;font-weight:600;margin-top:3px}\n.ranges{border-collapse:collapse;margin:3px 0 0 8px;font-family:monospace;font-size:.76rem}\n.ranges td{padding:1px 4px;vertical-align:middle}\n.r-from{color:#374151}.r-arr{color:#9ca3af;padding:0 2px}.r-to{color:#16a34a;font-weight:700}\n.pending-nvd{font-size:.78rem;color:#92400e;font-weight:600;margin-top:4px}\n.rec{padding:9px 16px;font-size:.85rem;font-weight:600;border-top:1px solid #e5e7eb}\n.rec.safe{color:#166534;background:#f0fdf4}.rec.danger{color:#991b1b;background:#fef2f2}.rec.warn{color:#92400e;background:#fffbeb}\n.wl-group{margin-bottom:16px}\n.wl-rule{display:inline-block;background:#e0f2fe;color:#0369a1;font-size:.78rem;font-weight:700;padding:2px 10px;border-radius:4px;margin-bottom:6px}\nfooter{text-align:center;padding:20px;font-size:.78rem;color:#9ca3af}\n</style>\n</head>\n<body>\n<header>\n  <h1>CVE Vulnerability Report</h1>\n  <div class=\"meta\">\n    Generated: ${esc(_formatDateTime(report.generatedAt))} &nbsp;|&nbsp;\n    Host: ${esc(report.hostname||'?')} &nbsp;|&nbsp;\n    IP: ${esc(report.ip||'?')} &nbsp;|&nbsp;\n    User: ${esc(report.username||'?')} &nbsp;|&nbsp;\n    Min Severity: <strong>${esc(report.minSeverity)}</strong> &nbsp;|&nbsp;\n    CVE 日期範圍：<strong>${esc(minYearLabel)}</strong>\n  </div>\n  <div class=\"dash\">\n    <div class=\"dash-grp\">\n      <div class=\"dash-grp-lbl\">軟體清單</div>\n      <div class=\"dash-cards\">\n        <div class=\"dc tot\"><div class=\"n\">${report.summary.totalSoftware}</div><div class=\"l\">軟體總計</div></div>\n        <span class=\"darr\">▶</span>\n        <div class=\"dc skip\"><div class=\"n\">${(report.whitelisted||[]).length}</div><div class=\"l\">白名單略過</div></div>\n        <span class=\"darr\">▶</span>\n        <div class=\"dc skip\"><div class=\"n\">${(report.skippedByPattern||[]).length+(report.skippedByDedup||[]).length}</div><div class=\"l\">子元件/重複略過</div><div class=\"s\">${(report.skippedByPattern||[]).length} 子元件・${(report.skippedByDedup||[]).length} 重複</div></div>\n        <span class=\"darr\">▶</span>\n        <div class=\"dc scan\"><div class=\"n\">${report.summary.queriedSoftware}</div><div class=\"l\">實際掃描</div></div>\n      </div>\n    </div>\n    <div class=\"dash-sep\"></div>\n    <div class=\"dash-grp\">\n      <div class=\"dash-grp-lbl\">掃描結果</div>\n      <div class=\"dash-cards\">\n        <div class=\"dc scan\"><div class=\"n\">${report.summary.queriedSoftware}</div><div class=\"l\">實際掃描</div></div>\n        <span class=\"darr\">▶</span>\n        <div class=\"dc ok\"><div class=\"n\">${cleanCount}</div><div class=\"l\">無弱點</div></div>\n        ${alreadySafe > 0 ? `<span class=\"darr\">▶</span>\n        <div class=\"dc ok\"><div class=\"n\">${alreadySafe}</div><div class=\"l\">版本已修正</div><div class=\"s\">CVE 已記錄</div></div>` : ''}\n        <span class=\"darr\">▶</span>\n        <div class=\"dc ${needUpgrade>0?'hi':'ok'}\"><div class=\"n\">${needUpgrade}</div><div class=\"l\">建議升級</div></div>\n        ${noRecCount>0?`<span class=\"darr\">▶</span><div class=\"dc neu\"><div class=\"n\">${noRecCount}</div><div class=\"l\">請手動確認</div></div>`:''}\n      </div>\n    </div>\n  </div>\n</header>\n<main>\n  <section>\n    <h2>升級建議摘要（共 ${report.summary.queriedSoftware} 筆：${needUpgrade} 需升級${noRecCount>0?'・'+noRecCount+' 請手動確認':''}・${cleanCount} 無弱點${alreadySafe>0?'・'+alreadySafe+' 版本已修正（詳見下方）':''}）</h2>\n    <table>\n      <thead><tr><th>Software</th><th>Publisher</th><th>已安裝版本</th><th>最低安全版本（需達到）</th><th>狀態</th></tr></thead>\n      <tbody>${tableRows||'<tr><td colspan=\"5\" style=\"color:#6b7280;text-align:center;padding:16px\">所有掃描軟體均無發現弱點</td></tr>'}</tbody>\n    </table>\n  </section>\n  <section>\n    <h2>CVE 詳細資訊（點擊展開）</h2>\n    ${detailsHTML||'<p class=\"sec-note\">所有掃描軟體均無發現需處理的 CVE</p>'}\n  </section>\n  ${fixedSection}\n  ${wlHTML}${patternHTML}${dedupHTML}\n</main>\n<footer>NIST NVD CVE Scanner &nbsp;·&nbsp; ${esc(report.generatedAt)}<br>This product uses data from the NVD API but is not endorsed or certified by the NVD.</footer>\n</body>\n</html>`;\n}\n\nif (typeof module !== 'undefined') {\n    module.exports = { buildHTMLReport };\n}\n\n\n// ─── UI elements ──────────────────────────────────────────────────────────────\nconst dropZone    = document.getElementById('drop-zone');\nconst fileInput   = document.getElementById('file-input');\nconst fileInfo    = document.getElementById('file-info');\nconst scanBtn     = document.getElementById('scan-btn');\nconst cancelBtn   = document.getElementById('cancel-btn');\nconst scanStatus  = document.getElementById('scan-status');\nconst portableList = document.getElementById('portable-list');\nconst manualList   = document.getElementById('manual-list');\n\n// ─── Portable rows ────────────────────────────────────────────────────────────\nfunction addPortableRow(name = '', version = '') {\n    const row = document.createElement('div');\n    row.className = 'portable-row';\n    row.innerHTML = '<input type=\"text\" class=\"pt-name\" placeholder=\"軟體名稱（例：Eclipse IDE）\">'\n                  + '<input type=\"text\" class=\"pt-ver\"  placeholder=\"版本號（例：202506）\">'\n                  + '<button type=\"button\" class=\"pt-del\" title=\"移除\">✕</button>';\n    row.querySelector('.pt-name').value = name;\n    row.querySelector('.pt-ver').value  = version;\n    row.querySelector('.pt-del').onclick = () => row.remove();\n    portableList.appendChild(row);\n}\ndocument.getElementById('add-portable-btn').addEventListener('click', () => addPortableRow());\n// Portables are pre-populated by the server-injected script (runs after this block).\n// portable-section visibility is also controlled by the server-injected script.\n\n// ─── Scan button state ────────────────────────────────────────────────────────\nfunction updateScanBtnState() {\n    if (activeTab === 'file') {\n        scanBtn.disabled = !scanData;\n        scanStatus.textContent = scanData ? `已就緒 — ${scanData.softwares.length} 筆軟體` : '請先上傳 scan.json';\n    } else {\n        const hasAny = [...manualList.querySelectorAll('.mn-name')].some(i => i.value.trim());\n        scanBtn.disabled = !hasAny;\n        scanStatus.textContent = hasAny ? '已就緒（手動輸入模式）' : '請新增至少一筆軟體';\n    }\n}\n\n// ─── Manual entry rows ────────────────────────────────────────────────────────\nfunction addManualRow(name = '', version = '') {\n    const row = document.createElement('div');\n    row.className = 'manual-row';\n    row.innerHTML = '<input type=\"text\" class=\"mn-name\" placeholder=\"軟體名稱（例：Eclipse IDE）\">'\n                  + '<input type=\"text\" class=\"mn-ver\"  placeholder=\"版本號（例：2025.06）\">'\n                  + '<button type=\"button\" class=\"mn-del\" title=\"移除\">✕</button>';\n    row.querySelector('.mn-name').value = name;\n    row.querySelector('.mn-ver').value  = version;\n    row.querySelector('.mn-del').onclick = () => { row.remove(); updateScanBtnState(); };\n    row.querySelector('.mn-name').addEventListener('input', updateScanBtnState);\n    manualList.appendChild(row);\n    updateScanBtnState();\n}\ndocument.getElementById('add-manual-btn').addEventListener('click', () => addManualRow());\naddManualRow(); // default empty row\n\n// ─── Tab switching ────────────────────────────────────────────────────────────\ndocument.querySelectorAll('.tab-btn').forEach(btn => {\n    btn.addEventListener('click', () => {\n        const target = btn.dataset.tab;\n        const fromBottom = btn.closest('.tab-bar-bottom') != null;\n        if (target === activeTab) {\n            if (fromBottom) document.querySelector('.tab-bar').scrollIntoView({ behavior: 'smooth', block: 'start' });\n            return;\n        }\n        activeTab = target;\n        document.querySelectorAll('.tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === target));\n        document.querySelectorAll('.tab-panel').forEach(p => p.classList.toggle('active', p.id === `tab-${target}`));\n        updateScanBtnState();\n        if (fromBottom) document.querySelector('.tab-bar').scrollIntoView({ behavior: 'smooth', block: 'start' });\n    });\n});\n\n// Restore settings\nconst LS = { key: 'nvd_api_key', wl: 'nvd_whitelist', sev: 'nvd_severity', year: 'nvd_min_year', max: 'nvd_max_cves' };\nconst $id = id => document.getElementById(id);\nconst restore = (id, lsKey) => { const v = localStorage.getItem(lsKey); if (v) $id(id).value = v; };\nrestore('api-key', LS.key);\nrestore('whitelist', LS.wl);\n// If the stored value is the old default (MEDIUM), clear it so the new HTML default (HIGH) takes effect.\nif (localStorage.getItem(LS.sev) === 'MEDIUM') localStorage.removeItem(LS.sev);\nrestore('min-severity', LS.sev);\nrestore('min-year', LS.year);\nrestore('max-cves', LS.max);\n\n// ─── File handling ────────────────────────────────────────────────────────────\nfunction loadScanFile(file) {\n    if (!file) return;\n    const reader = new FileReader();\n    reader.onload = e => {\n        try {\n            const data = JSON.parse(e.target.result);\n            if (!Array.isArray(data.softwares)) throw new Error('缺少 softwares 陣列（請確認為 cve-checker.js 或 findSW.ps1 產生的格式）');\n            scanData = data;\n            dropZone.classList.add('has-file');\n            dropZone.querySelector('.dz-icon').textContent = '✅';\n            dropZone.querySelector('.dz-label').textContent = file.name;\n            dropZone.querySelector('.dz-sub').textContent =\n                `${data.softwares.length} 筆軟體 · Host: ${data.hostname||'?'} · User: ${data.username||'?'}`;\n            fileInfo.style.display = 'block';\n            fileInfo.innerHTML = `<strong>${esc(file.name)}</strong> — ${data.softwares.length} 筆 &nbsp;·&nbsp; Host: <strong>${esc(data.hostname||'?')}</strong> &nbsp;·&nbsp; User: <strong>${esc(data.username||'?')}</strong> &nbsp;·&nbsp; Generated: ${esc((data.generatedAt||'').substring(0,10))}`;\n            updateScanBtnState();\n        } catch (err) {\n            alert(`JSON 格式錯誤：${err.message}`);\n        }\n    };\n    reader.readAsText(file, 'utf-8');\n}\n\nfileInput.addEventListener('change', e => loadScanFile(e.target.files[0]));\ndropZone.addEventListener('click', () => { if (!scanData) fileInput.click(); });\ndropZone.addEventListener('dragover', e => { e.preventDefault(); dropZone.classList.add('drag-over'); });\ndropZone.addEventListener('dragleave', e => { if (!dropZone.contains(e.relatedTarget)) dropZone.classList.remove('drag-over'); });\ndropZone.addEventListener('drop', e => {\n    e.preventDefault();\n    dropZone.classList.remove('drag-over');\n    loadScanFile(e.dataTransfer.files[0]);\n});\n\n// ─── Progress logging ─────────────────────────────────────────────────────────\nfunction logLineTo(tab, html, cls) {\n    const log = $id(`${tab}-progress-log`);\n    if (!log) return;\n    const d = document.createElement('div');\n    if (cls) d.className = cls;\n    d.innerHTML = html;\n    log.appendChild(d);\n    log.scrollTop = log.scrollHeight;\n}\nfunction logLine(html, cls) { logLineTo(activeTab, html, cls); }\nfunction logClear() { $id(`${activeTab}-progress-log`).innerHTML = ''; }\nfunction updateBar(done, total, cves) {\n    $id(`${activeTab}-progress-bar`).style.width = `${total > 0 ? Math.round(done/total*100) : 0}%`;\n    const left = Math.max(0, total - done);\n    $id(`${activeTab}-progress-stats`).innerHTML =\n        `<span>已掃描 <strong>${done}</strong>/${total}</span>` +\n        `<span>發現 <strong>${cves}</strong> 筆 CVE</span>` +\n        (left > 0 ? `<span>剩餘 <strong>${left}</strong> 項</span>` : '');\n}\n\n// ─── Main scan ────────────────────────────────────────────────────────────────\nscanBtn.addEventListener('click', async () => {\n    const isManual = activeTab === 'manual';\n    const scanTab  = activeTab;\n    if (!isManual && !scanData) return;\n\n    // Read settings\n    const apiKey     = $id('api-key').value.trim();\n    const wlRaw      = $id('whitelist').value;\n    const minSev     = $id('min-severity').value;\n    const minYearVal = $id('min-year').value.trim();\n    const minYear    = minYearVal ? (parseInt(minYearVal) || 0) : (new Date().getFullYear() - 5);\n    const maxCves    = Math.max(1, parseInt($id('max-cves').value) || 50);\n    const whitelist  = wlRaw.split(',').map(s => s.trim()).filter(Boolean);\n    const delay      = window.__NVD_DELAY__ ?? (apiKey ? 700 : 6500);\n    const minIdx     = SEVERITY_ORDER.indexOf(minSev);\n\n    // Persist settings\n    localStorage.setItem(LS.key,  apiKey);\n    localStorage.setItem(LS.wl,   wlRaw);\n    localStorage.setItem(LS.sev,  minSev);\n    localStorage.setItem(LS.year, minYearVal);\n    localStorage.setItem(LS.max,  String(maxCves));\n\n    abortController = new AbortController();\n    const signal = abortController.signal;\n\n    // UI: scanning state\n    scanBtn.disabled = true;\n    cancelBtn.style.display = 'inline-block';\n    cancelBtn.disabled = false;\n    scanStatus.textContent = '掃描中…';\n    document.querySelectorAll('.tab-btn').forEach(b => b.disabled = true);\n    $id(`${activeTab}-result-card`).style.display = 'none';\n    $id(`${activeTab}-progress-card`).style.display = 'block';\n    logClear();\n\n    // Revoke old download URLs for this tab only\n    for (const u of tabBlobUrls[activeTab]) URL.revokeObjectURL(u);\n    tabBlobUrls[activeTab] = [];\n\n    // ── Build query map ────────────────────────────────────────────────────────\n    const queryMap       = new Map();  // searchName → sw\n    let whitelisted    = [];\n    let skippedByPat   = [];\n    let skippedByDedup = [];\n    let portableEntries = [];\n\n    if (isManual) {\n        for (const row of manualList.querySelectorAll('.manual-row')) {\n            const name = row.querySelector('.mn-name').value.trim();\n            const ver  = row.querySelector('.mn-ver').value.trim();\n            if (name && !queryMap.has(name)) queryMap.set(name, { name, version: ver, publisher: '' });\n        }\n    } else {\n        for (const sw of scanData.softwares) {\n            const rule = matchWhitelist(sw, whitelist);\n            if (rule) { whitelisted.push({ name: sw.name, version: sw.version||'', publisher: sw.publisher||'', matchedRule: rule }); continue; }\n            if (shouldSkip(sw.name)) { skippedByPat.push({ name: sw.name, version: sw.version||'', publisher: sw.publisher||'' }); continue; }\n            const sn = cleanProductName(sw.name);\n            if (!queryMap.has(sn)) queryMap.set(sn, sw);\n            else skippedByDedup.push({ name: sw.name, version: sw.version||'', publisher: sw.publisher||'', mergedAs: sn });\n        }\n        // ── Add portable entries (bypass whitelist + skip-patterns) ──────────\n        for (const row of portableList.querySelectorAll('.portable-row')) {\n            const name = row.querySelector('.pt-name').value.trim();\n            const ver  = row.querySelector('.pt-ver').value.trim();\n            if (!name) continue;\n            portableEntries.push({ name, version: ver, publisher: '' });\n        }\n        for (const pt of portableEntries) {\n            if (!queryMap.has(pt.name)) queryMap.set(pt.name, pt);\n        }\n    }\n\n    const total        = queryMap.size;\n    const portableNote = portableEntries.length ? ` + <span class=\"l-b\">${portableEntries.length}</span> Portable` : '';\n    const modeTag      = isManual ? ' <span class=\"l-info\">[手動輸入]</span>' : '';\n    logLine(`<span class=\"l-info\">▶ 開始掃描</span> <span class=\"l-b\">${total}</span> 項軟體${portableNote}${modeTag}`\n        + (isManual ? '' : ` <span class=\"l-gray\">(白名單:${whitelisted.length} 子元件:${skippedByPat.length} 去重:${skippedByDedup.length})</span>`));\n    const apiKeyLabel = window.__NVD_PROXY__\n        ? (delay <= 700 ? '伺服器代理(已設定)' : '伺服器代理(未設定,6.5秒/次)')\n        : (apiKey ? '已設定' : '未設定(6.5秒/次)');\n    logLine(`<span class=\"l-gray\">設定：嚴重度≥${minSev}，年份≥${minYear}，每項最多${maxCves}筆，`\n        + `API Key:${apiKeyLabel}，預估${Math.ceil(total*delay/1000)}秒</span>`);\n    logLine('─'.repeat(64), 'l-gray');\n\n    const results      = [];\n    const cleanResults = [];\n    let idx = 0, totalCVEs = 0;\n    let scanSid = null;\n    const cpeBasesMap = new Map(); // searchName → cpeBases[] (only for portable items)\n\n    try {\n        // ── Shared CVE processing helper ──────────────────────────────────────\n        const processOneResult = (searchName, sw, resp) => {\n            const cpeBases = cpeBasesMap.get(searchName) || null;\n            const cpeBase  = cpeBases ? cpeBases[0] : null;\n\n            const allCVEs = (resp.vulnerabilities || []).map(v => ({ ...v, _cvss: getCvss(v.cve) }));\n\n            const checked = allCVEs\n                .filter(v => SEVERITY_ORDER.indexOf(v._cvss.severity) >= minIdx)\n                .filter(v => !minYear || new Date(v.cve.published).getFullYear() >= minYear)\n                .map(v => {\n                    const rel = cpeBases\n                        ? cveMatchesCPEBase(v.cve, cpeBases)\n                        : cveRelevanceCheck(v.cve, searchName);\n                    let finalRel = rel;\n                    let mis = null;\n                    if (rel === false) {\n                        mis = cpeBases\n                            ? `CPE 條目中無 ${cpeBases.map(b => `:${b.vendor}:${b.product}:`).join(' / ')}，非本軟體直接受影響的 CVE`\n                            : `CPE 條目中未含「${searchName}」相關字詞`;\n                    } else if (rel === true && sw.version && sw.version !== '?') {\n                        const exactCheck = cveExactVersionCheck(sw.version, v.cve, searchName, cpeBase);\n                        if (exactCheck && !exactCheck.affected) {\n                            finalRel = false;\n                            mis = `只有特定版本 ${exactCheck.versions.join('、')} 受影響，已安裝版本 ${sw.version} 不符`;\n                        }\n                    }\n                    return { ...v, _rel: finalRel, _mis: mis };\n                });\n\n            const mismatched = checked.filter(v => v._rel !== true).map(v => ({\n                id: v.cve.id, url: `https://nvd.nist.gov/vuln/detail/${v.cve.id}`,\n                severity: v._cvss.severity, cvssScore: v._cvss.score, cvssVersion: v._cvss.version,\n                description: v.cve.descriptions?.find(d => d.lang==='en')?.value || '',\n                published: v.cve.published, mismatchReason: v._mis,\n            }));\n\n            const relevant = checked\n                .filter(v => v._rel === true) // only confirmed-relevant CVEs (null = no CPE data → filtered out)\n                .sort((a, b) => (b.cve.published||'').localeCompare(a.cve.published||''));\n\n            mismatched.sort((a, b) => (b.published||'').localeCompare(a.published||''));\n\n            if (relevant.length === 0) {\n                logLine(`<span class=\"l-ok\">  ✓ 無弱點（${esc(minSev)}以上）</span>`);\n                cleanResults.push({\n                    software: { name: sw.name, version: sw.version||'', publisher: sw.publisher||'' },\n                    searchName, cpeBase: cpeBase || null, mismatchedCVEs: mismatched,\n                });\n                return { summary: `✓ 無弱點（取回${allCVEs.length}筆均不符條件）`, cveDetails: [] };\n            } else {\n                totalCVEs += relevant.length;\n                const cveObjs = relevant.map(v => ({\n                    id: v.cve.id,\n                    url: `https://nvd.nist.gov/vuln/detail/${v.cve.id}`,\n                    severity: v._cvss.severity,\n                    cvssScore: v._cvss.score,\n                    cvssVersion: v._cvss.version,\n                    description: v.cve.descriptions?.find(d => d.lang==='en')?.value || '',\n                    published: v.cve.published,\n                    lastModified: v.cve.lastModified,\n                    fixedVersion: extractFixedVersion(v.cve, searchName, cpeBase),\n                }));\n                const rec = getRecommendedVersion(relevant, searchName, cpeBase);\n                const sortedCves = [...cveObjs].sort((a, b) => (b.published||'').localeCompare(a.published||''));\n                for (const cve of sortedCves) {\n                    const cls = (cve.severity==='CRITICAL'||cve.severity==='HIGH') ? 'l-err' : 'l-warn';\n                    const fix = cve.fixedVersion\n                        ? `<span class=\"l-ok\"> ✓ 安全版本：${cve.fixedVersion.op==='>='?'≥':'>'} ${esc(cve.fixedVersion.version)}</span>`\n                        : `<span class=\"l-warn\"> ⚠ 無修復版本資訊</span>`;\n                    logLine(`  <span class=\"${cls}\"><a href=\"${cve.url}\" target=\"_blank\" rel=\"noopener\">${esc(cve.id)}</a> [${cve.severity} ${cve.cvssScore}]</span> <span class=\"l-gray\">${(cve.published||'').substring(0,10)}</span>${fix}`);\n                }\n                const hasUnfixed = cveObjs.some(c => !c.fixedVersion);\n                const needManualCheck = hasUnfixed;\n                if (rec) {\n                    if (!isSafeVersion(sw.version, rec)) {\n                        logLine(`  <span class=\"l-err\">→ 建議升級至 ${rec.op==='>='?'≥':'>'} ${esc(rec.version)}（目前：${esc(sw.version||'?')}）</span>`);\n                    } else if (needManualCheck) {\n                        logLine(`  <span class=\"l-warn\">→ 現有版本已達部分修復要求，但仍有 CVE 無修復版本資訊，請手動確認</span>`);\n                    } else {\n                        logLine(`  <span class=\"l-ok\">→ 目前版本 (${esc(sw.version)}) 已是安全版，無須升級</span>`);\n                    }\n                } else {\n                    logLine(`  <span class=\"l-warn\">→ 無修復版本資訊，請手動確認</span>`);\n                }\n                results.push({\n                    software: { name: sw.name, version: sw.version||'', publisher: sw.publisher||'', installDate: sw.installDate||null },\n                    searchName, cpeBase: cpeBase || null, recommendedVersion: rec, cveCount: cveObjs.length,\n                    cves: cveObjs, mismatchedCVEs: mismatched,\n                });\n                const maxSev = cveObjs.reduce((m, v) =>\n                    SEVERITY_ORDER.indexOf(v.severity) > SEVERITY_ORDER.indexOf(m) ? v.severity : m, 'NONE');\n                const cveDetails = sortedCves.map(cve => {\n                    const fixStr = cve.fixedVersion\n                        ? `✓ 安全版本：${cve.fixedVersion.op === '>=' ? '≥' : '>'} ${cve.fixedVersion.version}`\n                        : '⚠ 無修復版本資訊';\n                    return `  ${cve.id} [${cve.severity} ${cve.cvssScore}] ${(cve.published||'').substring(0,10)} ${fixStr}`;\n                });\n                const n = `${cveObjs.length}/${allCVEs.length}筆[${maxSev}]`;\n                if (!rec)                                                return { summary: `→ ${n}，請手動確認`,                                                                 cveDetails };\n                if (isSafeVersion(sw.version, rec) && !needManualCheck) return { summary: `✓ ${n}，目前版本已達修復版本`,                                                        cveDetails };\n                if (isSafeVersion(sw.version, rec))                     return { summary: `→ ${n}，現有版本已達部分修復要求，但仍有 CVE 無修復版本資訊，請手動確認`,              cveDetails };\n                return                                                          { summary: `→ ${n}，建議升級至 ${rec.op==='>='?'≥':'>'} ${rec.version}`, cveDetails };\n            }\n        };\n\n        // ── CPE pre-lookup for portable items ─────────────────────────────────\n        if (!isManual && portableEntries.length > 0) {\n            logLine(`<span class=\"l-gray\">── CPE 識別碼查找（${portableEntries.length} 個 Portable 軟體）…</span>`);\n            let firstCpe = true;\n            for (const pt of portableEntries) {\n                if (signal.aborted) break;\n                if (!firstCpe && !window.__NVD_PROXY__) await sleep(delay, signal);\n                firstCpe = false;\n                const nameWords = pt.name.toLowerCase().replace(/[^a-z0-9]/g, ' ').split(/\\s+/).filter(w => w.length >= 2);\n                try {\n                    let cpeData;\n                    if (window.__NVD_PROXY__) {\n                        const r = await fetch(`/api/cpe?keyword=${encodeURIComponent(pt.name)}`, { signal });\n                        if (!r.ok) throw new Error(`HTTP ${r.status}`);\n                        cpeData = await r.json();\n                    } else {\n                        const NVD_CPE_BASE = 'https://services.nvd.nist.gov/rest/json/cpes/2.0';\n                        const url = `${NVD_CPE_BASE}?keywordSearch=${encodeURIComponent(pt.name)}&resultsPerPage=10000`;\n                        cpeData = await nvdFetch(url, apiKey, signal);\n                    }\n                    const bases = findAllCPEBases(cpeData.products || [], nameWords);\n                    if (bases.length > 0) {\n                        cpeBasesMap.set(pt.name, bases);\n                        logLine(`<span class=\"l-gray\">  ${esc(pt.name)} → CPE: ${bases.map(b => `${b.vendor}:${b.product}`).join(' | ')}</span>`);\n                    } else {\n                        logLine(`<span class=\"l-warn\">  ${esc(pt.name)} → 未找到對應 CPE，改用關鍵字比對</span>`);\n                    }\n                } catch (e) {\n                    if (e.name === 'AbortError') throw e;\n                    logLine(`<span class=\"l-warn\">  ${esc(pt.name)} → CPE 查找失敗：${esc(e.message)}，改用關鍵字比對</span>`);\n                }\n            }\n            if (!firstCpe && !window.__NVD_PROXY__) await sleep(delay, signal); // delay before first CVE query\n            logLine('─'.repeat(64), 'l-gray');\n        }\n\n        if (window.__NVD_PROXY__) {\n            // ── Proxy mode: stream from server, process each item as it arrives ─\n            const scanResp = await fetch('/api/scan', {\n                method: 'POST',\n                headers: { 'Content-Type': 'application/json' },\n                body: JSON.stringify({\n                    keywords: [...queryMap.keys()],\n                    maxCves,\n                    meta: {\n                        minSeverity:      minSev,\n                        minYear,\n                        portableCount:    portableEntries.length,\n                        whitelistedCount: whitelisted.length,\n                        skippedCount:     skippedByPat.length,\n                        dedupCount:       skippedByDedup.length,\n                    },\n                }),\n                signal,\n            });\n            if (!scanResp.ok) throw new Error(`伺服器掃描失敗：HTTP ${scanResp.status}`);\n\n            const reader = scanResp.body.getReader();\n            const dec = new TextDecoder();\n            let buf = '';\n            outer: while (true) {\n                const { done, value } = await reader.read();\n                if (done) break;\n                buf += dec.decode(value, { stream: true });\n                let nl;\n                while ((nl = buf.indexOf('\\n')) !== -1) {\n                    const line = buf.slice(0, nl).trim();\n                    buf = buf.slice(nl + 1);\n                    if (!line) continue;\n                    const item = JSON.parse(line);\n                    if (item.done) break outer;\n                    if (item.sid) { scanSid = item.sid; continue; }\n                    const searchName = item.keyword;\n                    const sw = queryMap.get(searchName);\n                    if (!sw) continue;\n                    idx++;\n                    logLine(`<span class=\"l-gray\">[${idx}/${total}]</span> <span class=\"l-b\">${esc(sw.name)}</span> <span class=\"l-gray\">v${esc(sw.version||'?')}</span>`);\n                    logLine(`<span class=\"l-gray\">  search: \"${esc(searchName)}\"</span>`);\n                    let itemSummary = null, itemCveDetails = [];\n                    try {\n                        if (item.error) throw new Error(item.error);\n                        ({ summary: itemSummary, cveDetails: itemCveDetails } = processOneResult(searchName, sw, item.data));\n                    } catch (apiErr) {\n                        if (apiErr.name === 'AbortError') throw apiErr;\n                        itemSummary = `✗ 失敗：${apiErr.message}`;\n                        logLine(`  <span class=\"l-err\">✗ 掃描失敗：${esc(apiErr.message)}</span>`);\n                    }\n                    if (scanSid && itemSummary) {\n                        const logLines = [\n                            `[${idx}/${total}] ${sw.name} v${sw.version||'?'} ${itemSummary}`,\n                            ...itemCveDetails,\n                        ];\n                        fetch('/api/log', {\n                            method: 'POST',\n                            headers: { 'Content-Type': 'application/json' },\n                            body: JSON.stringify({ sid: scanSid, msg: logLines.join('\\n') }),\n                        }).catch(() => {});\n                    }\n                    updateBar(idx, total, totalCVEs);\n                }\n            }\n        } else {\n            // ── Direct mode: call NVD API per item ────────────────────────────\n            for (const [searchName, sw] of queryMap) {\n                if (signal.aborted) break;\n                idx++;\n                updateBar(idx - 1, total, totalCVEs);\n                logLine(`<span class=\"l-gray\">[${idx}/${total}]</span> <span class=\"l-b\">${esc(sw.name)}</span> <span class=\"l-gray\">v${esc(sw.version||'?')}</span>`);\n                logLine(`<span class=\"l-gray\">  search: \"${esc(searchName)}\"</span>`);\n\n                if (idx > 1) await sleep(delay, signal);\n                if (signal.aborted) break;\n\n                try {\n                    const resp = await searchCVEs(searchName, apiKey, maxCves, minYear, signal,\n                        msg => logLine(`  <span class=\"l-warn\">  🔄 ${msg}</span>`));\n                    processOneResult(searchName, sw, resp);\n                } catch (apiErr) {\n                    if (apiErr.name === 'AbortError') throw apiErr;\n                    logLine(`  <span class=\"l-err\">✗ 重試 ${MAX_FETCH_RETRIES} 次後仍失敗：${esc(apiErr.message)}</span>`);\n                    if (/CORS/i.test(apiErr.message)) {\n                        logLine(`  <span class=\"l-warn\">  提示：可能是 CORS 問題。請確認可直接連線 NIST NVD (services.nvd.nist.gov)，或改用本機 Node.js 版本。</span>`);\n                    }\n                }\n            }\n        }\n    } catch (e) {\n        if (e.name !== 'AbortError') logLine(`<span class=\"l-err\">✗ 未預期錯誤：${esc(e.message)}</span>`);\n    }\n\n    const cancelled = signal.aborted;\n    // Calculate status breakdown (also used by pills below)\n    const needUp      = results.filter(r => r.recommendedVersion && !isSafeVersion(r.software.version, r.recommendedVersion)).length;\n    const safeAlready = results.filter(r => r.recommendedVersion && isSafeVersion(r.software.version, r.recommendedVersion) && !r.cves.some(v => !v.fixedVersion)).length;\n    const manCheck    = results.filter(r => !r.recommendedVersion || (isSafeVersion(r.software.version, r.recommendedVersion) && r.cves.some(v => !v.fixedVersion))).length;\n    logLine('─'.repeat(64), 'l-gray');\n    if (cancelled) {\n        logLine('<span class=\"l-warn\">■ 掃描已取消</span>');\n    } else {\n        const parts = [];\n        if (safeAlready > 0) parts.push(`${safeAlready} 個已為最新版`);\n        if (needUp > 0) parts.push(`${needUp} 個建議升級`);\n        if (manCheck > 0) parts.push(`${manCheck} 個待確認`);\n        const breakdown = results.length > 0 && parts.length > 0 ? `，其中 ${parts.join('，')}` : '';\n        logLine(`<span class=\"l-ok l-b\">✓ 掃描完成</span> — ${idx} 項掃描・${cleanResults.length} 項無弱點，${results.length} 項有弱點${breakdown}`);\n    }\n    if (scanSid) {\n        const summaryMsg = cancelled\n            ? `■ 掃描取消（已完成 ${idx}/${total}）`\n            : `✓ 掃描完成 — ${idx}項掃描・${cleanResults.length}項無弱點，${results.length}項有弱點${needUp ? `（建議升級:${needUp}）` : ''}`;\n        fetch('/api/log', {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({ sid: scanSid, msg: summaryMsg }),\n        }).catch(() => {});\n    }\n    updateBar(idx, total, totalCVEs);\n\n    // ── Build report object (mirrors cve-checker.js structure) ────────────────\n    const report = {\n        generatedAt: new Date().toISOString(),\n        source: isManual ? 'Web (手動輸入)' : 'Web (scan.json)',\n        hostname: isManual ? '' : scanData.hostname || '',\n        ip: isManual ? '' : scanData.ip || '',\n        username: isManual ? '' : (scanData.username || '').toLowerCase(),\n        scanDate: isManual ? null : scanData.generatedAt,\n        minSeverity: minSev,\n        minYear,\n        summary: {\n            totalSoftware: isManual ? queryMap.size : (scanData.softwares.length + portableEntries.length),\n            queriedSoftware: idx,\n            affectedSoftware: results.length,\n            totalCVEs,\n        },\n        results,\n        cleanResults,\n        whitelisted,\n        skippedByPattern: skippedByPat,\n        skippedByDedup,\n        errors: [],\n    };\n\n    // ── Build report blobs ─────────────────────────────────────────────────────\n    const htmlStr  = buildHTMLReport(report);\n    const jsonStr  = JSON.stringify(report, null, 2);\n    const htmlBlob = new Blob([htmlStr], { type: 'text/html;charset=utf-8' });\n    const jsonBlob = new Blob([jsonStr], { type: 'application/json;charset=utf-8' });\n    const htmlUrl  = URL.createObjectURL(htmlBlob);\n    const jsonUrl  = URL.createObjectURL(jsonBlob);\n    tabBlobUrls[scanTab].push(htmlUrl, jsonUrl);\n    const slog = msg => {\n        if (!scanSid) return;\n        fetch('/api/log', { method: 'POST', headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({ sid: scanSid, msg }) }).catch(() => {});\n    };\n    $id(`${scanTab}-open-report-btn`).onclick = () => {\n        window.open(htmlUrl, '_blank');\n        slog('📄 使用者開啟報表（新分頁）');\n    };\n    if (!isManual) {\n        $id('file-dl-html').href = htmlUrl;\n        $id('file-dl-html').onclick = () => slog('⬇ 使用者下載報表 HTML (result.html)');\n        $id('file-dl-json').href = jsonUrl;\n        $id('file-dl-json').onclick = () => slog('⬇ 使用者下載 result.json');\n    }\n\n    const rc = $id(`${scanTab}-result-card`);\n    rc.style.display = 'block';\n    rc.scrollIntoView({ behavior: 'smooth' });\n\n    // Reset UI\n    document.querySelectorAll('.tab-btn').forEach(b => b.disabled = false);\n    scanBtn.disabled = false;\n    cancelBtn.style.display = 'none';\n    scanStatus.textContent = cancelled ? '已取消' : '掃描完成';\n    abortController = null;\n});\n\ncancelBtn.addEventListener('click', () => {\n    if (abortController) {\n        abortController.abort();\n        cancelBtn.disabled = true;\n        scanStatus.textContent = '取消中…';\n    }\n});\n\n// Show findSW.ps1 download hint only in proxy mode (injection runs before DOMContentLoaded)\nwindow.addEventListener('DOMContentLoaded', () => {\n    if (window.__NVD_PROXY__) {\n        document.getElementById('findsw-dl-hint').style.display = 'block';\n    }\n});\n</script>\n</body>\n</html>",
  "config": {
    "portableEnable": true,
    "whitelist": "Microsoft,Apple,Google",
    "portables": [
      {
        "name": "Node.js",
        "version": "24.0.0"
      }
    ],
    "requestDelay": 700
  }
};
